item.stdout:
  1	/**
  2	 * Everything that may come to the margins, and the one rule for when it may.
  3	 *
  4	 * Producers (comments, the room's notes, the Apparatus, the shelf, your other
  5	 * work, the charter, the dossier) hand the conductor `FlowItem`s. They never
  6	 * draw anything themselves. `decideSurface` decides what the writer sees:
  7	 *
  8	 *   flow / settling   nothing new. What is already on the page stays; new
  9	 *                     items wait, and the waiting count is all that shows.
 10	 *   working           a few items, nearest the cursor first.
 11	 *   stuck             the single best item for the paragraph the writer is
 12	 *                     stuck in, and whatever it links to.
 13	 *   away              no change.
 14	 *
 15	 * Pure: the conductor owns time, storage and the DOM.
 16	 */
 17	import type { FlowMode } from "./flow-state";
 18	
 19	export type FlowItemKind =
 20	  | "comment"
 21	  | "persona-note"
 22	  | "source"
 23	  | "work"
 24	  | "shelf"
 25	  | "echo"
 26	  | "charter"
 27	  | "amendment"
 28	  | "way-in";
 29	
 30	/** Which margin an item belongs to: the room's voices, or the writer's own. */
 31	export type FlowSide = "room" | "archive";
 32	
 33	export const SIDE_FOR: Record<FlowItemKind, FlowSide> = {
 34	  comment: "room",
 35	  "persona-note": "room",
 36	  source: "room",
 37	  work: "room",
 38	  charter: "room",
 39	  amendment: "room",
 40	  "way-in": "room",
 41	  shelf: "archive",
 42	  echo: "archive",
 43	};
 44	
 45	export const KIND_LABELS: Record<FlowItemKind, string> = {
 46	  comment: "Margin note",
 47	  "persona-note": "From the room",
 48	  source: "From the Apparatus",
 49	  work: "On the shelf",
 50	  shelf: "From your dossier",
 51	  echo: "You wrote",
 52	  charter: "The charter",
 53	  amendment: "Amendment",
 54	  "way-in": "A way in",
 55	};
 56	
 57	/** How much a kind matters before the writer's own habits weigh in. */
 58	const BASE_PRIORITY: Record<FlowItemKind, number> = {
 59	  comment: 0.9,
 60	  "persona-note": 0.75,
 61	  charter: 0.7,
 62	  amendment: 0.65,
 63	  // Only offered while stuck, when it should lead.
 64	  "way-in": 0.95,
 65	  source: 0.55,
 66	  echo: 0.55,
 67	  work: 0.5,
 68	  shelf: 0.45,
 69	};
 70	
 71	export interface WorkCard {
 72	  medium: "book" | "album" | "song" | "film";
 73	  title: string;
 74	  creator?: string;
 75	  year?: string;
 76	  cover?: string;
 77	  url?: string;
 78	}
 79	
 80	export interface FlowItem {
 81	  id: string;
 82	  kind: FlowItemKind;
 83	  /** Passages in this manuscript the item speaks to, verbatim. */
 84	  anchors: string[];
 85	  title: string;
 86	  /** Body text; for a streaming reply, what has arrived so far. */
 87	  body: string;
 88	  byline?: string;
 89	  /** Accent for the card's rule, e.g. a persona's color. */
 90	  color?: string;
 91	  createdAt: number;
