165	
166	export function decideSurface(
167	  items: readonly FlowItem[],
168	  context: SurfaceContext,
169	): Surfacing {
170	  const reasons: Record<string, string> = {};
171	  const live = items.filter((item) => {
172	    if (context.dismissed.has(item.id)) {
173	      reasons[item.id] = "dismissed";
174	      return false;
175	    }
176	    return true;
177	  });
178	  const ranked = live
179	    .filter((item) => {
180	      if (item.kind === "way-in" && context.mode !== "stuck") {
181	        reasons[item.id] = "held: a way in is only offered while stuck";
182	        return false;
183	      }
184	      if (item.kind === "way-in" && anchorOverlap(item, context.cursorText) <= 0.3) {
185	        reasons[item.id] = "held: a way in belongs to another passage";
186	        return false;
187	      }
188	      return true;
189	    })
190	    .map((item) => ({ item, score: scoreItem(item, context) }))
191	    .sort((a, b) => b.score - a.score);
192	
193	  let visible: FlowItem[];
194	  switch (context.mode) {
195	    case "flow":
196	    case "settling":
197	    case "away":
198	      // Nothing new arrives; what the writer already had stays put, except
199	      // in full flow, where the page stands alone.
200	      visible =
201	        context.mode === "flow"
202	          ? []
203	          : ranked.filter((r) => context.shown.has(r.item.id)).map((r) => r.item);
204	      for (const { item } of ranked)
205	        reasons[item.id] ??= visible.includes(item)
206	          ? "kept: already on the page"
207	          : `held: ${context.mode}`;
208	      break;
209	    case "stuck": {
210	      const best = ranked.find((r) => r.item.kind === "way-in") ?? ranked.find(
211	        (r) => anchorOverlap(r.item, context.cursorText) > 0.3,
212	      ) ?? ranked[0];
213	      const linked = new Set(best?.item.links ?? []);
214	      visible = best
215	        ? [best.item, ...ranked.filter((r) => linked.has(r.item.id)).map((r) => r.item)]
216	        : [];
217	      for (const { item, score } of ranked)
218	        reasons[item.id] = visible.includes(item)
219	          ? item === best?.item
220	            ? `stuck: best for this paragraph (${score.toFixed(2)})`
221	            : "stuck: linked to the best item"
222	          : "held: one thing at a time while stuck";
223	      break;
224	    }
225	    default: {
226	      const limit = context.workingLimit ?? 3;
227	      visible = ranked.slice(0, limit).map((r) => r.item);
228	      for (const [index, { item, score }] of ranked.entries())
229	        reasons[item.id] =
230	          index < limit
231	            ? `working: rank ${index + 1} (${score.toFixed(2)})`
232	            : `held: below the top ${limit}`;
233	    }
234	  }
235	  return { visible, held: live.length - visible.length, reasons };
236	}
237	
238	/**
239	 * Stack cards down one margin without overlap. Each card wants to sit level
240	 * with its anchor; when two collide the later one moves down, and obstacles
241	 * (the live tool card, the shelf) are stepped around.
242	 */
243	export function stackCards(
244	  cards: ReadonlyArray<{ id: string; top: number; height: number }>,
245	  obstacles: ReadonlyArray<{ top: number; height: number }> = [],
246	  gap = 10,
247	): Record<string, number> {
248	  const placed: Array<{ top: number; height: number }> = [...obstacles];
249	  const out: Record<string, number> = {};
250	  for (const card of [...cards].sort((a, b) => a.top - b.top)) {
251	    let top = Math.max(0, card.top);
252	    let moved = true;
253	    while (moved) {
254	      moved = false;
255	      for (const block of placed) {
256	        const overlaps =
257	          top < block.top + block.height + gap && top + card.height + gap > block.top;
258	        if (overlaps) {
259	          top = block.top + block.height + gap;
260	          moved = true;
261	        }
262	      }
263	    }
264	    placed.push({ top, height: card.height });
265	    out[card.id] = top;
266	  }
267	  return out;
268	}

