  1	/**
  2	 * Reading flow from the rhythm of the keys.
  3	 *
  4	 * Nothing here looks at the words — only at when they arrive and how many are
  5	 * taken back. Five readings:
  6	 *
  7	 *   away      no keys for minutes; nothing should change around the page
  8	 *   working   ordinary writing: pauses, rereads, small cuts
  9	 *   settling  a steady run has begun; the chrome starts to dim
 10	 *   flow      the run has held; the room goes quiet and the page stands alone
 11	 *   stuck     a long pause after cutting and circling — help may land now
 12	 *
 13	 * The readings are sticky on purpose. Entering flow takes a sustained run;
 14	 * leaving it takes a real pause (or the writer reaching for the room), never
 15	 * a single deletion or a glance away. A rewrite inside flow is still flow.
 16	 *
 17	 * Thresholds are not constants: `thresholdsFor` in `flow-profile.ts` derives
 18	 * them from how this writer actually pauses. Pure — `now` is passed in.
 19	 */
 20	
 21	export type FlowMode = "away" | "working" | "settling" | "flow" | "stuck";
 22	
 23	export interface KeySample {
 24	  at: number;
 25	  inserted: number;
 26	  deleted: number;
 27	}
 28	
 29	export interface FlowThresholds {
 30	  /** Longest gap between keys that still counts as one run. */
 31	  gapMs: number;
 32	  /** Run length before the chrome starts to dim. */
 33	  settleMs: number;
 34	  /** Run length before the page goes quiet. */
 35	  flowMs: number;
 36	  /** A pause this long, after churn, reads as stuck. */
 37	  stuckPauseMs: number;
 38	  /** A pause this long ends flow. */
 39	  exitPauseMs: number;
 40	  /** No keys for this long reads as away. */
 41	  awayMs: number;
 42	  /** Share of characters taken back that still counts as steady. */
 43	  maxDeleteRatio: number;
 44	  /** Share of the run's seconds that carried a key. */
 45	  minActiveRatio: number;
 46	}
 47	
 48	export const DEFAULT_THRESHOLDS: FlowThresholds = {
 49	  gapMs: 4_000,
 50	  settleMs: 30_000,
 51	  flowMs: 90_000,
 52	  stuckPauseMs: 18_000,
 53	  exitPauseMs: 25_000,
 54	  awayMs: 180_000,
 55	  maxDeleteRatio: 0.3,
 56	  minActiveRatio: 0.45,
 57	};
 58	
 59	export interface FlowContext {
 60	  /** 0..1 from `readStruggle` for the paragraph under the cursor. */
 61	  struggle?: number;
 62	  /** The writer has held the pointer over the room (margins, masthead). */
 63	  reaching?: boolean;
 64	}
 65	
 66	export interface FlowReading {
 67	  mode: FlowMode;
 68	  /** Length of the current (or last) run, ms. */
 69	  runMs: number;
 70	  /** Time since the last key, ms. */
 71	  pauseMs: number;
 72	  activeRatio: number;
 73	  deleteRatio: number;
 74	  /** Words a minute across the run, at five characters a word. */
 75	  wpm: number;
 76	  /** Deletions over the last minute of writing, as a share of all edits. */
 77	  recentChurn: number;
 78	  reason: string;
 79	}
 80	
 81	/** Keep only what `readFlow` can use; call on every sample. */
 82	export function trimSamples(
 83	  samples: KeySample[],
 84	  now: number,
 85	  keepMs = 10 * 60_000,
 86	): KeySample[] {
 87	  const cutoff = now - keepMs;
 88	  let start = 0;
 89	  while (start < samples.length && samples[start].at < cutoff) start++;
 90	  return start ? samples.slice(start) : samples;
 91	}
 92	
 93	export function readFlow(
 94	  samples: readonly KeySample[],
 95	  now: number,
 96	  previous: FlowMode,
 97	  t: FlowThresholds = DEFAULT_THRESHOLDS,
 98	  context: FlowContext = {},
 99	): FlowReading {
100	  const last = samples[samples.length - 1];
101	  if (!last)
102	    return reading("working", 0, Infinity, 0, 0, 0, 0, "No writing yet.");
103	  const pauseMs = Math.max(0, now - last.at);
104	
105	  // The current run: walk back while the gaps stay short.
106	  let first = samples.length - 1;
107	  while (first > 0 && samples[first].at - samples[first - 1].at <= t.gapMs)
108	    first--;
109	  const run = samples.slice(first);
110	  const runMs = last.at - run[0].at;
111	  let inserted = 0;
112	  let deleted = 0;
113	  const seconds = new Set<number>();
114	  for (const s of run) {
115	    inserted += s.inserted;
116	    deleted += s.deleted;
117	    seconds.add(Math.floor(s.at / 1000));
118	  }
119	  const deleteRatio = deleted / Math.max(1, inserted + deleted);
120	  const activeRatio =
121	    runMs < 1000 ? 1 : Math.min(1, seconds.size / Math.ceil(runMs / 1000));
122	  const wpm = runMs > 0 ? (inserted / 5) * (60_000 / runMs) : 0;
123	
124	  let recentIn = 0;
125	  let recentOut = 0;
126	  for (
127	    let i = samples.length - 1;
128	    i >= 0 && last.at - samples[i].at <= 60_000;
129	    i--
130	  ) {
131	    recentIn += samples[i].inserted;
132	    recentOut += samples[i].deleted;
133	  }
134	  const recentChurn = recentOut / Math.max(1, recentIn + recentOut);
135	  const steady =
136	    deleteRatio <= t.maxDeleteRatio && activeRatio >= t.minActiveRatio;
137	  const at = (mode: FlowMode, reason: string) =>
138	    reading(
139	      mode,
140	      runMs,
141	      pauseMs,
142	      activeRatio,
143	      deleteRatio,
144	      wpm,
145	      recentChurn,
146	      reason,
147	    );
148	
149	  if (pauseMs >= t.awayMs) return at("away", "No keys for a while.");
150	
151	  if (context.reaching) return at("working", "Reached for the room.");
152	
153	  if (previous === "flow") {
154	    if (pauseMs >= t.exitPauseMs)
155	      return at("working", "A long pause ended the run.");
156	    return at("flow", "Still in the run.");
157	  }
158	
159	  const circling = recentChurn >= 0.4 || (context.struggle ?? 0) >= 0.5;
160	  if (pauseMs >= t.stuckPauseMs && circling)
161	    return at("stuck", "A long pause after cutting and circling.");
162	  if (previous === "stuck" && pauseMs >= t.gapMs)
163	    return at("stuck", "Still paused.");
164	
165	  if (pauseMs <= t.gapMs && steady) {
166	    if (runMs >= t.flowMs) return at("flow", "A steady run held.");
167	    if (runMs >= t.settleMs) return at("settling", "A steady run is building.");
168	  }
169	  if (previous === "settling" && pauseMs <= t.gapMs && runMs >= t.settleMs)
170	    return at("settling", "The run continues.");
171	  return at("working", steady ? "Writing." : "Revising.");
172	}
173	
174	function reading(
175	  mode: FlowMode,
176	  runMs: number,
177	  pauseMs: number,
178	  activeRatio: number,
179	  deleteRatio: number,
180	  wpm: number,
181	  recentChurn: number,
182	  reason: string,
183	): FlowReading {
184	  return {
185	    mode,
186	    runMs,
187	    pauseMs,
188	    activeRatio,
189	    deleteRatio,
190	    wpm,
191	    recentChurn,
192	    reason,
193	  };
194	}
195	
196	/** The quiet modes: nothing new may appear around the page. */
197	export function isQuiet(mode: FlowMode): boolean {
198	  return mode === "flow" || mode === "settling";
199	}

