   161	  return p.hours
   162	    .map((minutes, hour) => ({ minutes, hour }))
   163	    .filter((h) => h.minutes > 0)
   164	    .sort((a, b) => b.minutes - a.minutes)
   165	    .slice(0, top)
   166	    .map((h) => h.hour);
   167	}
