    if (!active()) return;
    const entry = entries[entries.length - 1];
    if (!entry) return;
    upsert({
      id: `source:${entry.id}`,
      kind: "source",
      anchors: [d.anchor],
      title: entry.title,
      body: entry.why || entry.snippet || "",
      byline: [entry.author, entry.publisher, entry.year]
        .filter(Boolean)
        .join(" · "),
      createdAt: Date.now(),
      url: entry.url,
    });
