  1	/**
  2	 * One door for every typed judgement Twyne asks for.
  3	 *
  4	 * Callers used to reach for `api.systemOne.ask` directly, which fixed the
  5	 * model to whatever Twyne's server was configured with. This routes by the
  6	 * writer's choice in Settings instead:
  7	 *
  8	 *   twyne     → the Convex action, Twyne's hosted Jev (unchanged behaviour)
  9	 *   typesafe  → the same action with the writer's key; TypeSafe refuses
 10	 *               browser requests, so the server relays it (and stores nothing)
 11	 *   endpoint  → a direct browser request to a System One-compatible server,
 12	 *               e.g. Kev on this computer. Nothing goes through Twyne.
 13	 *
 14	 * A writer who chose their own model never silently falls back to Twyne's:
 15	 * if their endpoint is down, the judgement fails and each caller's existing
 16	 * offline path takes over. Choosing a local model is often a privacy choice.
 17	 */
 18	import type { ConvexClient } from "convex/browser";
 19	import { api } from "../../convex/_generated/api";
 20	import {
 21	  judgementQuestions,
 22	  validJudgementResponse,
 23	  type JudgementQuestion,
 24	} from "../../convex/lib/judgementContract";
 25	import type { JudgementSettings } from "../types";
 26	import { loadAiSettingsFromIdb } from "./idb";
 27	
 28	export interface JudgementRequest {
 29	  state: Record<string, string>;
 30	  questions: Record<string, JudgementQuestion>;
 31	  model?: string;
 32	}
 33	
 34	export interface JudgementResult {
 35	  ok: boolean;
 36	  model?: string;
 37	  answers?: Record<string, unknown>;
 38	  usage?: { input_tokens: number; output_tokens: number };
 39	  transport?: "notorganic" | "direct" | "none" | "byok" | "endpoint";
 40	  error?: string;
 41	  /** Round trip in ms, as the browser saw it. */
 42	  latencyMs?: number;
 43	}
 44	
 45	export const DEFAULT_ENDPOINT_MODEL = "kev-latest";
 46	export const DEFAULT_TYPESAFE_MODEL = "jev-latest";
 47	export const LOCAL_KEV_URL = "http://127.0.0.1:8009";
 48	
 49	let cached: JudgementSettings | null | undefined;
 50	if (typeof window !== "undefined") {
 51	  window.addEventListener("twyne:ai-settings-saved", () => {
 52	    cached = undefined;
 53	  });
 54	}
 55	
 56	async function currentSettings(): Promise<JudgementSettings | null> {
 57	  if (cached !== undefined) return cached;
 58	  cached = (await loadAiSettingsFromIdb())?.judgement ?? null;
 59	  return cached;
 60	}
 61	
 62	/** A trimmed base URL, or null when it is not an http(s) URL. */
 63	export function normalizeEndpointUrl(value: string | undefined): string | null {
 64	  const raw = value
 65	    ?.trim()
 66	    .replace(/\/+$/, "")
 67	    .replace(/\/v1\/systemone$/, "");
 68	  if (!raw) return null;
 69	  try {
 70	    const url = new URL(raw);
 71	    return url.protocol === "http:" || url.protocol === "https:"
 72	      ? url.toString().replace(/\/+$/, "")
 73	      : null;
 74	  } catch {
 75	    return null;
 76	  }
 77	}
 78	
 79	/** Short, human description of where judgements go, for status lines. */
 80	export function describeJudgement(settings: JudgementSettings | null): string {
 81	  if (!settings || settings.source === "twyne") return "Jev, through Twyne";
 82	  if (settings.source === "typesafe")
 83	    return `${settings.typesafeModel || DEFAULT_TYPESAFE_MODEL} on your TypeSafe key`;
 84	  const url = normalizeEndpointUrl(settings.endpointUrl);
 85	  return `${settings.endpointModel || DEFAULT_ENDPOINT_MODEL} at ${url ?? "your endpoint"}`;
 86	}
 87	
 88	async function askEndpoint(
 89	  settings: JudgementSettings,
 90	  request: JudgementRequest,
 91	): Promise<JudgementResult> {
 92	  const base = normalizeEndpointUrl(settings.endpointUrl);
 93	  if (!base) return { ok: false, transport: "endpoint", error: "unconfigured" };
 94	  let questions: ReturnType<typeof judgementQuestions>;
 95	  try {
 96	    questions = judgementQuestions(request.questions);
 97	  } catch {
 98	    return { ok: false, transport: "endpoint", error: "malformed" };
 99	  }
100	  const started = performance.now();
101	  let res: Response;
102	  try {
103	    res = await fetch(`${base}/v1/systemone`, {
104	      method: "POST",
105	      // Local CPU models are slow on a cold cache; give them room.
106	      signal: AbortSignal.timeout(120_000),
107	      headers: {
108	        "Content-Type": "application/json",
109	        ...(settings.endpointKey?.trim()
110	          ? { Authorization: `Bearer ${settings.endpointKey.trim()}` }
111	          : {}),
112	      },
113	      body: JSON.stringify({
114	        model:
115	          request.model ?? (settings.endpointModel || DEFAULT_ENDPOINT_MODEL),
116	        state: request.state,
117	        questions,
118	      }),
119	    });
120	  } catch {
121	    return { ok: false, transport: "endpoint", error: "network" };
122	  }
123	  const latencyMs = Math.round(performance.now() - started);
124	  if (!res.ok) {
125	    const error =
126	      res.status === 401 || res.status === 403
127	        ? "unauthorized"
128	        : res.status === 429
129	          ? "rate limited"
130	          : res.status === 422
131	            ? "malformed"
132	            : `http ${res.status}`;
133	    return { ok: false, transport: "endpoint", error, latencyMs };
134	  }
135	  let body: unknown;
136	  try {
137	    body = await res.json();
138	  } catch {
139	    return { ok: false, transport: "endpoint", error: "provider", latencyMs };
140	  }
141	  if (!validJudgementResponse(body, request.questions))
142	    return { ok: false, transport: "endpoint", error: "provider", latencyMs };
143	  return {
144	    ok: true,
145	    transport: "endpoint",
146	    model: body.model,
147	    answers: body.answers,
148	    usage: body.usage,
149	    latencyMs,
150	  };
151	}
152	
153	/**
154	 * Ask the writer's judgement model. Same request and result shape as the
155	 * `systemOne.ask` action, so call sites swap one line.
156	 */
157	export async function askJudgement(
158	  client: ConvexClient | null | undefined,
159	  request: JudgementRequest,
160	  override?: JudgementSettings | null,
161	): Promise<JudgementResult> {
162	  const settings = override !== undefined ? override : await currentSettings();
163	  if (settings?.source === "endpoint") return askEndpoint(settings, request);
164	  if (!client) return { ok: false, transport: "none", error: "signed out" };
165	  const started = performance.now();
166	  const key =
167	    settings?.source === "typesafe" ? settings.typesafeKey?.trim() : undefined;
168	  if (settings?.source === "typesafe" && !key)
169	    return { ok: false, transport: "byok", error: "unconfigured" };
170	  const result = (await client.action(api.systemOne.ask, {
171	    state: request.state,
172	    questions: request.questions,
173	    ...(key
174	      ? {
175	          apiKey: key,
176	          model:
177	            request.model ??
178	            (settings?.typesafeModel || DEFAULT_TYPESAFE_MODEL),
179	        }
180	      : request.model
181	        ? { model: request.model }
182	        : {}),
183	  })) as JudgementResult;
184	  return { ...result, latencyMs: Math.round(performance.now() - started) };
185	}
186	
187	/** A one-question round trip for the Settings "Test" button. */
188	export async function testJudgement(
189	  client: ConvexClient | null | undefined,
190	  settings: JudgementSettings,
191	): Promise<JudgementResult> {
192	  return askJudgement(
193	    client,
194	    {
195	      state: { text: "The package arrived two weeks late and damaged." },
196	      questions: {
197	        complaint: {
198	          type: "noul",
199	          instructions: "Is `text` a complaint?",
200	        },
201	      },
202	    },
203	    settings,
204	  );
205	}

