168	  if (settings?.source === "typesafe" && !key)
169	    return { ok: false, transport: "byok", error: "unconfigured" };
170	  const result = (await client.action(api.systemOne.ask, {
171	    state: request.state,
172	    questions: request.questions,
173	    ...(key
174	      ? {
175	          apiKey: key,
176	          model:
177	            request.model ??
178	            (settings?.typesafeModel || DEFAULT_TYPESAFE_MODEL),
179	        }
180	      : request.model
181	        ? { model: request.model }
182	        : {}),
183	  })) as JudgementResult;
