  7	 * paragraphs to a handful of candidates cheaply and privately, and Jev then
  8	 * reads the handful and says which actually bear on each other.
  9	 */
 10	
 11	const STOP = new Set(
 12	  "a about above after again against all am an and any are as at be because been before being below between both but by can could did do does doing down during each few for from further had has have having he her here hers herself him himself his how i if in into is it its itself just me more most my myself no nor not now of off on once only or other our ours ourselves out over own same she should so some such than that the their theirs them themselves then there these they this those through to too under until up very was we were what when where which while who whom why will with would you your yours yourself yourselves also one two may might must shall us like even much many well still yet ever never always often really quite rather".split(
 13	    " ",
 14	  ),
 15	);
 16	
 17	export function tokens(text: string): string[] {
 18	  return text
 19	    .toLowerCase()
 20	    .replace(/[’']s\b/g, "")
 21	    .split(/[^\p{L}\p{N}]+/u)
 22	    .filter((w) => w.length > 2 && !STOP.has(w) && !/^\d+$/.test(w))
 23	    .map(stem);
 24	}
 25	
 26	/** Crude suffix folding, enough that "libraries" meets "library". */
 27	function stem(word: string): string {
 28	  if (word.length > 5 && word.endsWith("ies")) return word.slice(0, -3) + "y";
 29	  if (word.length > 5 && word.endsWith("ing")) return word.slice(0, -3);
 30	  if (word.length > 4 && word.endsWith("ed")) return word.slice(0, -2);
 31	  if (word.length > 3 && word.endsWith("s") && !word.endsWith("ss"))
 32	    return word.slice(0, -1);
 33	  return word;
 34	}
 35	
 36	export interface Passage {
 37	  id: string;
 38	  text: string;
 39	  /** Where it lives — a folio id, or the current manuscript. */
 40	  source: string;
 41	  sourceName?: string;
 42	}
 43	
 44	interface Indexed extends Passage {
 45	  weights: Map<string, number>;
 46	  norm: number;
 47	}
 48	
 49	export interface PassageIndex {
 50	  passages: Indexed[];
 51	  idf: Map<string, number>;
 52	}
 53	
 54	export function buildIndex(passages: readonly Passage[]): PassageIndex {
 55	  const df = new Map<string, number>();
 56	  const counted = passages.map((p) => {
 57	    const counts = new Map<string, number>();
 58	    for (const t of tokens(p.text)) counts.set(t, (counts.get(t) ?? 0) + 1);
 59	    for (const t of counts.keys()) df.set(t, (df.get(t) ?? 0) + 1);
 60	    return { passage: p, counts };
 61	  });
 62	  const n = passages.length;
 63	  const idf = new Map<string, number>();
 64	  for (const [t, d] of df) idf.set(t, Math.log(1 + n / d));
 65	  return {
 66	    idf,
 67	    passages: counted.map(({ passage, counts }) => {
 68	      const weights = new Map<string, number>();
 69	      let sum = 0;
 70	      for (const [t, c] of counts) {
 71	        const w = (1 + Math.log(c)) * (idf.get(t) ?? 0);
 72	        weights.set(t, w);
 73	        sum += w * w;
 74	      }
 75	      return { ...passage, weights, norm: Math.sqrt(sum) };
 76	    }),
 77	  };
 78	}
 79	
 80	export interface Match {
 81	  passage: Passage;
 82	  score: number;
 83	  /** The rare words the two share, strongest first — shown on the card. */
 84	  shared: string[];
 85	}
 86	
 87	export function similar(
 88	  text: string,
 89	  index: PassageIndex,
 90	  options: { k?: number; min?: number; exclude?: (p: Passage) => boolean } = {},
 91	): Match[] {
 92	  const { k = 3, min = 0.12, exclude } = options;
 93	  const query = new Map<string, number>();
 94	  for (const t of tokens(text)) query.set(t, (query.get(t) ?? 0) + 1);
 95	  let qNorm = 0;
 96	  const qWeights = new Map<string, number>();
 97	  for (const [t, c] of query) {
 98	    const w = (1 + Math.log(c)) * (index.idf.get(t) ?? Math.log(2));
 99	    qWeights.set(t, w);
100	    qNorm += w * w;
101	  }
102	  qNorm = Math.sqrt(qNorm);
103	  if (!qNorm) return [];
104	
105	  const matches: Match[] = [];
106	  for (const p of index.passages) {
107	    if (!p.norm || exclude?.(p)) continue;
108	    let dot = 0;
109	    const shared: Array<[string, number]> = [];
110	    for (const [t, w] of qWeights) {
111	      const pw = p.weights.get(t);
112	      if (pw) {
113	        dot += w * pw;
114	        shared.push([t, w * pw]);
115	      }
116	    }
117	    // One shared word is a coincidence, not a connection.
118	    if (shared.length < 2) continue;
119	    const score = dot / (qNorm * p.norm);
120	    if (score >= min)
121	      matches.push({
122	        passage: { id: p.id, text: p.text, source: p.source, sourceName: p.sourceName },
123	        score,
124	        shared: shared.sort((a, b) => b[1] - a[1]).slice(0, 4).map(([t]) => t),
125	      });
126	  }
127	  return matches.sort((a, b) => b.score - a.score).slice(0, k);
128	}
129	
130	/** Split plain text into paragraphs worth indexing. */
131	export function paragraphs(text: string, minChars = 80): string[] {
132	  return text
133	    .split(/\n\s*\n|\n/)
134	    .map((p) => p.replace(/\s+/g, " ").trim())
135	    .filter((p) => p.length >= minChars);
136	}
137	
138	/**
139	 * Titles a paragraph names: curly- or straight-quoted runs of capitalised
140	 * words, plus any italic spans the editor hands in. Jev decides later which
141	 * are real works worth a card.
142	 */
143	export function workCandidates(text: string, italics: readonly string[] = []): string[] {
144	  const found = new Set<string>();
145	  const quoted = /[“"]([^”"]{2,80})[”"]/g;
146	  let m: RegExpExecArray | null;
147	  while ((m = quoted.exec(text))) {
148	    const title = m[1].trim().replace(/[,.;:!?]+$/, "");
149	    const words = title.split(/\s+/);
150	    const capitals = words.filter((w) => /^[\p{Lu}\d]/u.test(w)).length;
151	    if (words.length <= 9 && capitals >= Math.ceil(words.length / 2)) found.add(title);
152	  }
153	  for (const span of italics) {
154	    const title = span.trim().replace(/[,.;:!?]+$/, "");
155	    const words = title.split(/\s+/);
156	    if (words.length >= 1 && words.length <= 9 && /^[\p{Lu}\d]/u.test(title))
157	      found.add(title);
158	  }
159	  return [...found].slice(0, 4);
160	}

