item.stdout:
  1	/**
  2	 * Covers for the works a draft names — books from Open Library, records and
  3	 * songs from MusicBrainz with art from the Cover Art Archive.
  4	 *
  5	 * Only the title (and a creator, when the draft gave one) leaves the device,
  6	 * and only when the writer has cover lookups on. Results are cached for the
  7	 * session and MusicBrainz is held to its one-request-a-second rule. Cards
  8	 * show a title, creator, year and cover, and link out — never lyrics.
  9	 */
 10	import { loadMetaFromIdb } from "./idb";
 11	import type { WorkCard } from "./flow-items";
 12	import { COVER_LOOKUP_SETTING_KEY } from "./in-flow-events";
 13	
 14	export { COVER_LOOKUP_SETTING_KEY };
 15	
 16	type Medium = WorkCard["medium"];
 17	type Fetch = typeof fetch;
 18	
 19	const cache = new Map<string, WorkCard | null>();
 20	let lastMusicBrainz = 0;
 21	
 22	export async function coverLookupsEnabled(): Promise<boolean> {
 23	  return (await loadMetaFromIdb<boolean>(COVER_LOOKUP_SETTING_KEY)) !== false;
 24	}
 25	
 26	export async function lookupWork(
 27	  title: string,
 28	  medium: Medium,
 29	  options: { fetchImpl?: Fetch; enabled?: boolean; now?: () => number } = {},
 30	): Promise<WorkCard | null> {
 31	  const enabled = options.enabled ?? (await coverLookupsEnabled());
 32	  if (!enabled || !title.trim() || medium === "film") return null;
 33	  const key = `${medium}:${title.trim().toLowerCase()}`;
 34	  if (cache.has(key)) return cache.get(key) ?? null;
 35	  const fetchImpl = options.fetchImpl ?? fetch;
 36	  let card: WorkCard | null = null;
 37	  try {
 38	    card =
 39	      medium === "book"
 40	        ? await openLibrary(title, fetchImpl)
 41	        : await musicBrainz(title, medium, fetchImpl, options.now ?? Date.now);
 42	  } catch {
 43	    card = null;
 44	  }
 45	  cache.set(key, card);
 46	  return card;
 47	}
 48	
 49	async function openLibrary(title: string, fetchImpl: Fetch): Promise<WorkCard | null> {
 50	  const url = `https://openlibrary.org/search.json?${new URLSearchParams({
 51	    q: title,
 52	    limit: "1",
 53	    fields: "key,title,author_name,first_publish_year,cover_i",
 54	  })}`;
 55	  const response = await fetchImpl(url, { headers: { Accept: "application/json" } });
 56	  if (!response.ok) return null;
 57	  const body = (await response.json()) as {
 58	    docs?: Array<{
 59	      key?: string;
 60	      title?: string;
 61	      author_name?: string[];
 62	      first_publish_year?: number;
 63	      cover_i?: number;
 64	    }>;
 65	  };
 66	  const doc = body.docs?.[0];
 67	  if (!doc?.title || !similarTitle(doc.title, title)) return null;
 68	  return {
 69	    medium: "book",
 70	    title: doc.title,
 71	    creator: doc.author_name?.[0],
 72	    year: doc.first_publish_year ? String(doc.first_publish_year) : undefined,
 73	    cover: doc.cover_i
 74	      ? `https://covers.openlibrary.org/b/id/${doc.cover_i}-M.jpg`
 75	      : undefined,
 76	    url: doc.key ? `https://openlibrary.org${doc.key}` : undefined,
 77	  };
 78	}
 79	
 80	async function musicBrainz(
 81	  title: string,
 82	  medium: "album" | "song",
 83	  fetchImpl: Fetch,
 84	  now: () => number,
 85	): Promise<WorkCard | null> {
 86	  const wait = lastMusicBrainz + 1_100 - now();
 87	  if (wait > 0) await new Promise((resolve) => setTimeout(resolve, wait));
 88	  lastMusicBrainz = now();
 89	  const entity = medium === "album" ? "release-group" : "recording";
 90	  const url = `https://musicbrainz.org/ws/2/${entity}/?${new URLSearchParams({
 91	    query: medium === "album" ? `releasegroup:"${title}"` : `recording:"${title}"`,
 92	    limit: "1",
 93	    fmt: "json",
 94	  })}`;
 95	  const response = await fetchImpl(url, { headers: { Accept: "application/json" } });
 96	  if (!response.ok) return null;
 97	  const body = (await response.json()) as {
 98	    "release-groups"?: MbItem[];
 99	    recordings?: Array<MbItem & { releases?: Array<{ "release-group"?: { id?: string; title?: string } }> }>;
100	  };
101	  const item =
102	    medium === "album" ? body["release-groups"]?.[0] : body.recordings?.[0];
103	  if (!item?.title || !similarTitle(item.title, title)) return null;
104	  const group =
105	    medium === "album"
106	      ? item.id
107	      : (item as { releases?: Array<{ "release-group"?: { id?: string } }> })
108	          .releases?.[0]?.["release-group"]?.id;
109	  return {
110	    medium,
111	    title: item.title,
112	    creator: item["artist-credit"]?.[0]?.name,
113	    year: item["first-release-date"]?.slice(0, 4) || undefined,
114	    cover: group
115	      ? `https://coverartarchive.org/release-group/${group}/front-250`
116	      : undefined,
117	    url: item.id
118	      ? `https://musicbrainz.org/${entity}/${item.id}`
119	      : undefined,
120	  };
121	}
122	
123	interface MbItem {
124	  id?: string;
125	  title?: string;
126	  "first-release-date"?: string;
127	  "artist-credit"?: Array<{ name?: string }>;
128	}
129	
130	/** Search engines always return something; only keep a real match. */
131	export function similarTitle(found: string, wanted: string): boolean {
132	  const norm = (s: string) =>
133	    s.toLowerCase().replace(/^(the|a|an)\s+/, "").replace(/[^\p{L}\p{N}]+/gu, "");
134	  const a = norm(found);
135	  const b = norm(wanted);
136	  return !!a && !!b && (a === b || a.startsWith(b) || b.startsWith(a));
137	}
138	
139	export function __resetMediaCacheForTests(): void {
140	  cache.clear();
141	  lastMusicBrainz = 0;
142	}

